#[tauri::command]
fn list_browser_downloads() -> Vec<BrowserDownload> {
    let directory = downloads_directory();
    let mut records = browser_downloads()
        .lock()
        .unwrap_or_else(|error| error.into_inner())
        .clone();
    if let Ok(entries) = std::fs::read_dir(&directory) {
        for entry in entries.flatten() {
            let path = entry.path();
            let Ok(file_type) = entry.file_type() else {
                continue;
            };
            if !file_type.is_file() {
                continue;
            }
            let path_string = path.to_string_lossy().to_string();
            if records.iter().any(|record| record.path == path_string) {
                continue;
            }
            records.push(BrowserDownload {
                id: path_string.clone(),
                name: path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or("download")
                    .to_string(),
                path: path_string,
                url: String::new(),
                state: "done".to_string(),
                size: entry.metadata().ok().map(|metadata| metadata.len()),
                started_at: entry
                    .metadata()
                    .ok()
                    .and_then(|metadata| metadata.modified().ok())
                    .map(|modified| chrono::DateTime::<chrono::Utc>::from(modified).to_rfc3339())
                    .unwrap_or_else(|| chrono::Utc::now().to_rfc3339()),
                finished_at: None,
            });
        }
    }
    records.sort_by(|left, right| right.started_at.cmp(&left.started_at));
    records.truncate(100);
    records
}

#[tauri::command]
fn browser_downloads_dir() -> String {
    downloads_directory().to_string_lossy().to_string()
}

// Tauri commands (IPC handlers)

/// An inline attachment sent from the composer (paste/drop/pick). Images carry
/// a base64 payload the model can see; other files are preserved and surfaced
/// to the model by name/type rather than being silently dropped.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct AttachmentInput {
    pub name: String,
    pub mime: String,
    /// Base64-encoded file data (no data-URI prefix)
    pub data: String,
}

/// Decoded byte length of a base64 payload.
///
/// `String::len()` counts the encoded characters, which overstates a file by
/// roughly a third. The UI shows this number on every attachment card, so it
/// has to be the size of the file the user will download.
fn decoded_base64_len(data: &str) -> u64 {
    let padding = data.bytes().rev().take_while(|byte| *byte == b'=').count();
    ((data.len() as u64) * 3 / 4).saturating_sub(padding as u64)
}

fn build_attachments(attachments: Vec<AttachmentInput>) -> Vec<ravenbot_core::Attachment> {
    attachments
        .into_iter()
        .map(|a| {
            let is_image = a.mime.trim().to_lowercase().starts_with("image/");
            ravenbot_core::Attachment {
                id: Uuid::new_v4(),
                name: a.name,
                mime_type: a.mime,
                size: decoded_base64_len(&a.data),
                path: String::new(),
                data: Some(a.data),
                is_image,
            }
        })
        .collect()
}

/// Local-first default provider/model for newly created bots (Ollama unless
/// RAVENBOT_DEFAULT_PROVIDER / RAVENBOT_DEFAULT_MODEL override it).
/// Place the main window on a named or 1-based monitor for testing.
///
/// Hyprland/X11 monitor-relative dispatches are compositor-specific and can
/// move a Wayland window outside its output. Tauri's own monitor list is the
/// portable source of truth: `RAVENBOT_WINDOW_MONITOR` accepts a monitor name
/// (`DP-4`) or a 1-based index after sorting monitors by x position. The size
/// is clamped to the monitor so a test window cannot be larger than the screen.
fn place_main_window(app: &tauri::AppHandle) {
    let Ok(spec) = std::env::var("RAVENBOT_WINDOW_MONITOR") else {
        return;
    };
    let spec = spec.trim().to_string();
    if spec.is_empty() {
        return;
    }
    let Some(window) = app.get_window("main") else {
        return;
    };
    let Ok(mut monitors) = window.available_monitors() else {
        return;
    };
    monitors.sort_by_key(|monitor| monitor.position().x);
    tracing::info!(
        monitors = ?monitors
            .iter()
            .map(|monitor| (
                monitor.name().map(String::as_str).unwrap_or("?").to_string(),
                monitor.position().x,
                monitor.position().y,
                monitor.size().width,
                monitor.size().height,
            ))
            .collect::<Vec<_>>(),
        "available monitors for window placement"
    );
    let monitor = if let Ok(index) = spec.parse::<usize>() {
        monitors.get(index.saturating_sub(1))
    } else {
        monitors.iter().find(|monitor| {
            monitor
                .name()
                .map(|name| name.eq_ignore_ascii_case(&spec))
                .unwrap_or(false)
        })
    };
    let Some(monitor) = monitor else {
        tracing::warn!(monitor = %spec, "RAVENBOT_WINDOW_MONITOR did not match a monitor");
        return;
    };
    let scale = monitor.scale_factor();
    let size = monitor.size().to_logical::<f64>(scale);
    let position = monitor.position().to_logical::<f64>(scale);
    if std::env::var("RAVENBOT_WINDOW_FULLSCREEN").is_ok() {
        // A tiled compositor ignores set_position/set_size. Borderless
        // fullscreen is the placement it must honor, so the test window really
        // is on the requested monitor.
        // Tauri 2 exposes fullscreen as a boolean; the compositor chooses the
        // monitor. The window is opened on the focused output for this test.
        let _ = window.set_fullscreen(true);
        let _ = window.set_focus();
        tracing::info!(
            monitor = monitor.name().map(String::as_str).unwrap_or("?"),
            "Placed the main window fullscreen for testing"
        );
        return;
    }
    let width = 1280.0_f64.min(size.width);
    let height = 820.0_f64.min(size.height);
    let x = position.x + ((size.width - width) / 2.0).max(0.0);
    let y = position.y + ((size.height - height) / 2.0).max(0.0);
    let _ = window.set_size(tauri::LogicalSize::new(width, height));
    let _ = window.set_position(tauri::LogicalPosition::new(x, y));
    let _ = window.set_focus();
    tracing::info!(
        monitor = monitor.name().map(String::as_str).unwrap_or("?"),
        x,
        y,
        width,
        height,
        "Placed the main window for testing"
    );
}

fn default_bot_model() -> (String, String) {
    let provider = std::env::var("RAVENBOT_DEFAULT_PROVIDER")
        .ok()
        .filter(|p| !p.trim().is_empty())
        .unwrap_or_else(|| "ollama".to_string());
    let model = std::env::var("RAVENBOT_DEFAULT_MODEL")
        .ok()
        .filter(|m| !m.trim().is_empty())
        .unwrap_or_else(|| match provider.as_str() {
            "openrouter" => "anthropic/claude-3.5-sonnet".to_string(),
            "anthropic" => "claude-3-5-sonnet-20241022".to_string(),
            "openai" => "gpt-4o".to_string(),
            _ => "llama3.1".to_string(),
        });
    (provider, model)
}

/// The model a provider starts on when the owner has not chosen one.
///
/// Kept next to the resolver rather than in the frontend so `create_bot`,
/// office provisioning and the settings panel all agree on what "default"
/// means.
fn default_model_for_provider(provider: &str) -> &'static str {
    match provider.trim().to_ascii_lowercase().as_str() {
        "opencode-go" => "deepseek-v4.1-flash",
        "opencode" => "claude-sonnet-4-5",
        "commandcode" => "deepseek/deepseek-v4-flash",
        "anthropic" | "claude" => "claude-3-7-sonnet-20250219",
        "openai" => "gpt-4o",
        "openrouter" => "anthropic/claude-3.5-sonnet",
        "deepseek" => "deepseek-chat",
        "groq" => "llama-3.3-70b-versatile",
        "gemini" => "gemini-2.0-flash",
        "xai" | "grok" => "grok-2-latest",
        "mistral" => "mistral-large-latest",
        "together" => "meta-llama/Llama-3.3-70B-Instruct-Turbo",
        "perplexity" => "llama-3.1-sonar-large-128k-online",
        "cohere" => "command-r-plus",
        "mimo" => "mimo-v2.5",
        "cline" => "claude-sonnet-4-5",
        "tokenrouter" => "deepseek/deepseek-v4.1-flash",
        _ => "llama3.1",
    }
}

/// Resolve the model new agents should start on, with the reason it won.
///
/// Order matters: an explicit default beats everything, then env for headless
/// installs, then **a provider that actually has a key**. The last step is the
/// one that was missing. A user who added an OpenCode Go key and never opened
/// the model picker used to get `ollama/llama3.1` for every new bot, and the
/// office failed with "no model provider available" while a perfectly good
/// key sat in the database.
async fn resolve_default_model_with_source(
    pool: &sqlx::SqlitePool,
) -> (String, String, &'static str) {
    let provider = ravenbot_db::queries::AppSettingsQueries::get(pool, "default_provider")
        .await
        .ok()
        .flatten();
    let model = ravenbot_db::queries::AppSettingsQueries::get(pool, "default_model")
        .await
        .ok()
        .flatten();
    if let (Some(p), Some(m)) = (provider, model) {
        if !p.trim().is_empty() && !m.trim().is_empty() {
            return (p, m, "settings");
        }
    }

    if let Ok(p) = std::env::var("RAVENBOT_DEFAULT_PROVIDER") {
        let p = p.trim().to_string();
        if !p.is_empty() {
            let m = std::env::var("RAVENBOT_DEFAULT_MODEL")
                .ok()
                .filter(|m| !m.trim().is_empty())
                .unwrap_or_else(|| default_model_for_provider(&p).to_string());
            return (p, m, "env");
        }
    }

    // A bot that is already configured is the strongest signal of what works
    // in this installation. The most recently updated one wins, so setting up
    // an agent and then creating an office reuses the model that agent
    // demonstrably runs on instead of an unrelated key that happens to be newer.
    if let Ok(rows) = sqlx::query_as::<_, (String, String)>(
        "SELECT json_extract(config, '$.model_provider'), json_extract(config, '$.model_id')
         FROM bots
         WHERE TRIM(COALESCE(json_extract(config, '$.model_provider'), '')) <> ''
           AND TRIM(COALESCE(json_extract(config, '$.model_id'), '')) <> ''
         ORDER BY updated_at DESC
         LIMIT 20",
    )
    .fetch_all(pool)
    .await
    {
        for (p, m) in rows {
            if !p.trim().is_empty() && !m.trim().is_empty() {
                return (p, m, "bot");
            }
        }
    }

    // A configured key is stronger evidence of intent than a compiled-in
    // fallback. Most recently updated first, so the provider someone just
    // connected is the one their first office uses.
    let custom_models: std::collections::HashMap<String, String> =
        sqlx::query_as::<_, (String, String)>("SELECT id, default_model FROM custom_providers")
            .fetch_all(pool)
            .await
            .unwrap_or_default()
            .into_iter()
            .map(|(id, model)| (id.to_ascii_lowercase(), model))
            .collect();

    if let Ok(rows) = sqlx::query_as::<_, (String,)>(
        "SELECT provider FROM provider_keys
         WHERE TRIM(api_key) <> ''
         ORDER BY updated_at DESC",
    )
    .fetch_all(pool)
    .await
    {
        for (p,) in rows {
            let p = p.trim().to_ascii_lowercase();
            if p.is_empty() {
                continue;
            }
            let model = custom_models
                .get(&p)
                .map(|m| m.trim().to_string())
                .filter(|m| !m.is_empty())
                .unwrap_or_else(|| default_model_for_provider(&p).to_string());
            return (p, model, "configured");
        }
    }

    let (p, m) = default_bot_model();
    (p, m, "default")
}

/// Resolve the model new agents should start on (provider, model).
async fn resolve_default_model(pool: &sqlx::SqlitePool) -> (String, String) {
    let (provider, model, _) = resolve_default_model_with_source(pool).await;
    (provider, model)
}

#[tauri::command]
async fn create_bot(
    state: State<'_, AppState>,
    name: String,
    description: String,
    avatar_url: Option<String>,
    avatar_style: Option<String>,
) -> Result<Bot, String> {
    let mut bot = Bot::new(name, description);
    if let Some(url) = avatar_url {
        bot.avatar_url = Some(url);
    }
    if let Some(style) = avatar_style {
        bot.avatar_style = Some(style);
    }
    let (default_provider, default_model) = resolve_default_model(state.db.pool()).await;
    bot.config.model_provider = default_provider;
    bot.config.model_id = default_model;

    ravenbot_db::queries::BotQueries::insert(state.db.pool(), &bot)
        .await
        .map_err(|e| e.to_string())?;

    Ok(bot)
}

/// The app setting that remembers which agent designs offices.
const DEFAULT_AGENT_SETTING: &str = "default_agent_id";
const DEFAULT_AGENT_NAME: &str = "The Raven";

/// The default agent's mandate.
///
/// This is the one agent the app asks for before it can design an office. It
/// is an architect, not a worker: it reads the live capability catalog and
/// writes the charter and roster, then gets out of the way.
const DEFAULT_AGENT_PROMPT: &str = "\
You are The Raven, the default agent and Office Architect for this RAVENBOT installation.

You do not do the office's work. You design offices: turn a name and a partial mission into a goal, a binding policy, and the smallest team that can deliver it, using only the tools that exist on this machine.

**What you do**
- Infer the missing mission from the name and any context you were given.
- Write a policy with checkable rules: evidence, file locations, handoffs, and honesty about failure.
- Hire 3-6 agents, exactly one of them the lead. Give every role a mandate with ownership, the artifact it produces, how it proves the work, and what it hands on.
- Assign only skills, MCP connectors, and plugins from the catalog you are given. Never invent an id.

**What you produce**
A single JSON object with `goal`, `policy`, `roles`, and `question`. No prose around it. If one detail would materially change the work, put it in `question` and still return a usable team.

**How you verify**
Every role has a real artifact and a way to prove it. Every tool id appears in the catalog. The lead can delegate. A roster of titles with no evidence is a failed design.";

fn default_agent_skills() -> Vec<String> {
    [
        "delegate",
        "research",
        "file_read",
        "file_write",
        "memory_recall",
        "memory_save",
        "todo",
        "ask_user",
        "note_manager",
    ]
    .iter()
    .map(|s| (*s).to_string())
    .collect()
}

/// The installed default agent, if one has been chosen.
///
/// Falls back to the first orchestrator so an existing fleet does not have to
/// re-run onboarding; the choice is persisted so the same agent keeps the role.
async fn find_default_agent(pool: &sqlx::SqlitePool) -> Option<Bot> {
    if let Ok(Some(id)) =
        ravenbot_db::queries::AppSettingsQueries::get(pool, DEFAULT_AGENT_SETTING).await
    {
        if let Ok(id) = Uuid::parse_str(id.trim()) {
            if let Ok(Some(bot)) = ravenbot_db::queries::BotQueries::get(pool, id).await {
                return Some(bot);
            }
        }
    }
    if let Ok(bots) = ravenbot_db::queries::BotQueries::list(pool).await {
        if let Some(bot) = bots.into_iter().find(|b| b.is_orchestrator) {
            let _ = ravenbot_db::queries::AppSettingsQueries::set(
                pool,
                DEFAULT_AGENT_SETTING,
                &bot.id.to_string(),
            )
            .await;
            return Some(bot);
        }
    }
    None
}

#[tauri::command]
async fn get_default_agent(state: State<'_, AppState>) -> Result<Option<Bot>, String> {
    Ok(find_default_agent(state.db.pool()).await)
}

#[tauri::command]
async fn set_default_agent(state: State<'_, AppState>, bot_id: Uuid) -> Result<Bot, String> {
    let mut bot = ravenbot_db::queries::BotQueries::get(state.db.pool(), bot_id)
        .await
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "Agent not found".to_string())?;
    if !bot.is_orchestrator {
        bot.is_orchestrator = true;
        ravenbot_db::queries::BotQueries::update(state.db.pool(), &bot)
            .await
            .map_err(|e| e.to_string())?;
    }
    ravenbot_db::queries::AppSettingsQueries::set(
        state.db.pool(),
        DEFAULT_AGENT_SETTING,
        &bot.id.to_string(),
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(bot)
}

/// Create (or adopt) the agent that designs offices.
///
/// The onboarding flow asks for this once, after a provider is connected. It
/// is a real bot, not a hidden setting: the user can rename it, change its
/// model, inspect its prompt, or replace it later from Settings.
#[tauri::command]
async fn create_default_agent(
    state: State<'_, AppState>,
    name: Option<String>,
    provider: Option<String>,
    model: Option<String>,
) -> Result<Bot, String> {
    let name = name
        .as_deref()
        .map(str::trim)
        .filter(|n| !n.is_empty())
        .unwrap_or(DEFAULT_AGENT_NAME)
        .to_string();
    let (provider, model) = match (
        provider.as_deref().map(str::trim).filter(|p| !p.is_empty()),
        model.as_deref().map(str::trim).filter(|m| !m.is_empty()),
    ) {
        (Some(p), Some(m)) => (p.to_string(), m.to_string()),
        _ => resolve_default_model(state.db.pool()).await,
    };

    // Never create an agent that cannot answer. Check both the live manager
    // (hydrated at startup) and the database, so opening onboarding before the
    // manager has finished hydrating does not produce a false "no key" error.
    let manager_has = {
        let manager = state.runtime.provider_manager().lock().await;
        manager.has_key(&provider)
    };
    let db_has = ravenbot_db::queries::ProviderKeyQueries::get(state.db.pool(), &provider)
        .await
        .ok()
        .flatten()
        .map(|k| !k.trim().is_empty())
        .unwrap_or(false);
    let has_key = manager_has
        || db_has
        || provider.eq_ignore_ascii_case("ollama")
        || provider.eq_ignore_ascii_case("local");
    if !has_key {
        return Err(format!(
            "No API key is configured for {provider}. Connect it in Settings first."
        ));
    }

    let existing = ravenbot_db::queries::BotQueries::list(state.db.pool())
        .await
        .map_err(|e| e.to_string())?
        .into_iter()
        .find(|b| b.name.eq_ignore_ascii_case(&name));

    let bot = if let Some(mut bot) = existing {
        bot.config.model_provider = provider;
        bot.config.model_id = model;
        bot.is_orchestrator = true;
        bot.approval_mode = ravenbot_core::ApprovalMode::Full;
        if bot.rank.as_deref().map(str::trim).unwrap_or("").is_empty() {
            bot.rank = Some(DEFAULT_AGENT_NAME.to_string());
        }
        if bot
            .specialty
            .as_deref()
            .map(str::trim)
            .unwrap_or("")
            .is_empty()
        {
            bot.specialty = Some("Office design and orchestration".to_string());
        }
        if bot
            .config
            .custom_prompt
            .as_deref()
            .map(str::trim)
            .filter(|p| !p.is_empty())
            .is_none()
        {
            bot.config.custom_prompt = Some(DEFAULT_AGENT_PROMPT.to_string());
        }
        if bot.skills.is_empty() {
            bot.skills = default_agent_skills();
        }
        ravenbot_db::queries::BotQueries::update(state.db.pool(), &bot)
            .await
            .map_err(|e| e.to_string())?;
        bot
    } else {
        let mut bot = Bot::new(&name, "The Raven — default agent and office architect");
        bot.rank = Some(DEFAULT_AGENT_NAME.to_string());
        bot.specialty = Some("Office design and orchestration".to_string());
        bot.is_orchestrator = true;
        bot.approval_mode = ravenbot_core::ApprovalMode::Full;
        bot.avatar_color = "#8b5cf6".to_string();
        bot.config.model_provider = provider;
        bot.config.model_id = model;
        bot.config.custom_prompt = Some(DEFAULT_AGENT_PROMPT.to_string());
        bot.skills = default_agent_skills();
        ravenbot_db::queries::BotQueries::insert(state.db.pool(), &bot)
            .await
            .map_err(|e| e.to_string())?;
        bot
    };

    ravenbot_db::queries::AppSettingsQueries::set(
        state.db.pool(),
        DEFAULT_AGENT_SETTING,
        &bot.id.to_string(),
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(bot)
}

#[tauri::command]
async fn list_bots(state: State<'_, AppState>) -> Result<Vec<Bot>, String> {
    ravenbot_db::queries::BotQueries::list(state.db.pool())
        .await
        .map_err(|e| e.to_string())
}

#[tauri::command]
async fn get_bot(state: State<'_, AppState>, bot_id: Uuid) -> Result<Option<Bot>, String> {
    ravenbot_db::queries::BotQueries::get(state.db.pool(), bot_id)
        .await
        .map_err(|e| e.to_string())
}

/// List audit-log entries across every bot, newest first.
///
/// Tool arguments never leave the database: the returned rows carry only the
/// allow-listed fields the audit view displays.
#[tauri::command]
async fn list_audit_entries(
    state: State<'_, AppState>,
    bot_id: Option<String>,
    kinds: Option<Vec<String>>,
    search: Option<String>,
    since: Option<String>,
    until: Option<String>,
    limit: Option<u32>,
    offset: Option<u32>,
) -> Result<ravenbot_governance::AuditPage, String> {
    let query = ravenbot_governance::AuditQuery {
        bot_id,
        kinds: kinds.unwrap_or_default(),
        search,
        since,
        until,
        limit,
        offset,
    };
    state.runtime.audit_logger().query(&query).await
}

/// The maximum size of a signed audit export, in bytes. The entry cap is the
/// primary bound; this also catches unusually large serialized rows.
const MAX_AUDIT_EXPORT_BYTES: u64 = 128 * 1024 * 1024;

/// Resolve a user-chosen export path and refuse dangerous targets.
///
/// The save dialog normally supplies an absolute path, but IPC callers are not
/// trusted to do so. An export must be JSON, must not be a directory, and must
/// never overwrite the live database or its WAL/SHM siblings.
fn audit_export_path(raw: &str) -> Result<std::path::PathBuf, String> {
    let raw = raw.trim();
    if raw.is_empty() {
        return Err("Choose where to save the audit export.".to_string());
    }
    if raw.len() > 4096 {
        return Err("The export path is too long.".to_string());
    }
    let path = std::path::PathBuf::from(raw);
    if !path.is_absolute() {
        return Err("Choose an absolute export path.".to_string());
    }
    if path
        .extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| extension.eq_ignore_ascii_case("json"))
        != Some(true)
    {
        return Err("Audit exports must use a .json file name.".to_string());
    }
    let parent = path
        .parent()
        .filter(|parent| parent.is_dir())
        .ok_or_else(|| "The export folder does not exist.".to_string())?;
    let parent = parent
        .canonicalize()
        .map_err(|error| format!("Could not resolve the export folder: {error}"))?;
    let name = path
        .file_name()
        .ok_or_else(|| "The export path has no file name.".to_string())?;
    let path = parent.join(name);
    if path.is_dir() {
        return Err("That export path is a directory.".to_string());
    }

    let root = ravenbot_core::raven_root();
    let protected = [
        root.join("ravenbot.db"),
        root.join("ravenbot.db-wal"),
        root.join("ravenbot.db-shm"),
    ];
    let resolved = path.canonicalize().unwrap_or_else(|_| path.clone());
    if protected.iter().any(|candidate| {
        candidate
            .canonicalize()
            .unwrap_or_else(|_| candidate.clone())
            == resolved
    }) {
        return Err("Refusing to overwrite the RAVENBOT database.".to_string());
    }
    Ok(path)
}

/// Write via a same-directory temporary file so a failed export does not leave
/// a half-written audit document behind.
fn write_audit_export(path: &std::path::Path, contents: &[u8]) -> Result<(), String> {
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| "The export path has no usable file name.".to_string())?;
    let temp = path.with_file_name(format!(".{file_name}.tmp-{}", Uuid::new_v4()));
    std::fs::write(&temp, contents)
        .map_err(|error| format!("Could not write the audit export: {error}"))?;
    #[cfg(windows)]
    if path.exists() {
        if let Err(error) = std::fs::remove_file(path) {
            let _ = std::fs::remove_file(&temp);
            return Err(format!("Could not replace the existing export: {error}"));
        }
    }
    if let Err(error) = std::fs::rename(&temp, path) {
        let _ = std::fs::remove_file(&temp);
        return Err(format!("Could not finish the audit export: {error}"));
    }
    Ok(())
}

#[derive(Debug)]
struct VerifiedAuditExport {
    count: u64,
    exported_at: String,
    public_key: String,
}

/// Verify a signed audit export without trusting its filename or caller.
fn verify_audit_export_bytes(bytes: &[u8]) -> Result<VerifiedAuditExport, String> {
    if bytes.len() as u64 > MAX_AUDIT_EXPORT_BYTES {
        return Err("The audit export is larger than the 128 MB limit.".to_string());
    }
    let export: ravenbot_governance::AuditExport = serde_json::from_slice(bytes)
        .map_err(|error| format!("This is not a RAVENBOT audit export: {error}"))?;
    if export.payload.format != ravenbot_governance::AUDIT_EXPORT_FORMAT {
        return Err("This file is not a RAVENBOT audit export.".to_string());
    }
    if export.payload.version != ravenbot_governance::AUDIT_EXPORT_VERSION {
        return Err(format!(
            "Unsupported audit export version {}.",
            export.payload.version
        ));
    }
    if export.signature.algorithm != "ed25519" {
        return Err("The audit export does not use an Ed25519 signature.".to_string());
    }
    if export.payload.count != export.payload.entries.len() as u64 {
        return Err("The audit export count does not match its entries.".to_string());
    }
    let payload_bytes = serde_json::to_vec(&export.payload)
        .map_err(|error| format!("Could not serialize the audit payload: {error}"))?;
    if !ravenbot_sync::BundleSigner::verify_with(
        &payload_bytes,
        &export.signature.signature,
        &export.signature.public_key,
    ) {
        return Err("The audit export signature does not match its contents.".to_string());
    }
    Ok(VerifiedAuditExport {
        count: export.payload.count,
        exported_at: export.payload.exported_at,
        public_key: export.signature.public_key,
    })
}

struct BuiltAuditExport {
    json: String,
    count: u64,
    bytes: usize,
    sha256: String,
    public_key: String,
}

/// Build the signed export document shared by the manual and scheduled paths.
async fn build_audit_export(
    pool: &sqlx::SqlitePool,
    filters: ravenbot_governance::AuditExportFilters,
) -> Result<BuiltAuditExport, String> {
    let query = ravenbot_governance::AuditQuery {
        bot_id: filters.bot_id.clone(),
        kinds: filters.kinds.clone(),
        search: filters.search.clone(),
        since: filters.since.clone(),
        until: filters.until.clone(),
        limit: None,
        offset: None,
    };
    let entries = ravenbot_governance::AuditLogger::new(pool.clone())
        .export(&query)
        .await?;
    let signer = ravenbot_sync::bundle::open_signer(pool.clone()).await?;
    let payload = ravenbot_governance::AuditExportPayload {
        format: ravenbot_governance::AUDIT_EXPORT_FORMAT.to_string(),
        version: ravenbot_governance::AUDIT_EXPORT_VERSION,
        exported_at: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, false),
        filters,
        count: entries.len() as u64,
        entries,
    };
    let payload_bytes = serde_json::to_vec(&payload)
        .map_err(|error| format!("Could not serialize the audit export: {error}"))?;
    let signature = signer.sign(&payload_bytes);
    let public_key = signer.public_key_b64();
    let export = ravenbot_governance::AuditExport {
        payload,
        signature: ravenbot_governance::AuditExportSignature {
            algorithm: "ed25519".to_string(),
            public_key: public_key.clone(),
            signature,
        },
    };
    let mut json = serde_json::to_string_pretty(&export)
        .map_err(|error| format!("Could not serialize the audit export: {error}"))?;
    json.push('\n');
    let bytes = json.as_bytes();
    if bytes.len() as u64 > MAX_AUDIT_EXPORT_BYTES {
        return Err(
            "The audit export is larger than the 128 MB limit. Narrow the filters.".to_string(),
        );
    }
    Ok(BuiltAuditExport {
        count: export.payload.count,
        bytes: bytes.len(),
        sha256: file_version(bytes),
        public_key,
        json,
    })
}

/// Export the matching audit entries to a signed JSON document.
///
/// The Ed25519 signature covers the serialized payload, including the redacted
/// entries and the filters that produced them. The returned summary includes a
/// SHA-256 of the exact file for out-of-band checksum comparison.
#[tauri::command]
async fn export_audit_log(
    state: State<'_, AppState>,
    path: String,
    bot_id: Option<String>,
    kinds: Option<Vec<String>>,
    search: Option<String>,
    since: Option<String>,
    until: Option<String>,
) -> Result<serde_json::Value, String> {
    let path = audit_export_path(&path)?;
    let filters = ravenbot_governance::AuditExportFilters {
        bot_id,
        kinds: kinds.unwrap_or_default(),
        search,
        since,
        until,
    };
    let export = build_audit_export(state.db.pool(), filters).await?;
    write_audit_export(&path, export.json.as_bytes())?;
    Ok(serde_json::json!({
        "path": path.to_string_lossy(),
        "count": export.count,
        "bytes": export.bytes,
        "sha256": export.sha256,
        "public_key": export.public_key,
    }))
}

/// Verify the Ed25519 signature on a previously exported audit file.
#[tauri::command]
async fn verify_audit_export(
    state: State<'_, AppState>,
    path: String,
) -> Result<serde_json::Value, String> {
    let path = audit_export_path(&path)?;
    let metadata = std::fs::metadata(&path)
        .map_err(|error| format!("Could not read the audit export: {error}"))?;
    if metadata.len() > MAX_AUDIT_EXPORT_BYTES {
        return Err("The audit export is larger than the 128 MB limit.".to_string());
    }
    let bytes = std::fs::read(&path)
        .map_err(|error| format!("Could not read the audit export: {error}"))?;
    let verified = verify_audit_export_bytes(&bytes)?;
    let signer = ravenbot_sync::bundle::open_signer(state.db.pool().clone()).await?;
    let trusted_by_this_installation = verified.public_key == signer.public_key_b64();
    Ok(serde_json::json!({
        "valid": true,
        "trusted": trusted_by_this_installation,
        "path": path.to_string_lossy(),
        "count": verified.count,
        "exported_at": verified.exported_at,
        "public_key": verified.public_key,
        "sha256": file_version(&bytes),
    }))
}

/// Permanently delete audit entries older than the chosen number of days.
#[tauri::command]
async fn prune_audit_log(state: State<'_, AppState>, older_than_days: u32) -> Result<u64, String> {
    state.runtime.audit_logger().prune(older_than_days).await
}

const AUDIT_RETENTION_KEY: &str = "audit_retention_days";
const AUDIT_EXPORT_DIR_KEY: &str = "audit_export_dir";
const AUDIT_EXPORT_INTERVAL_KEY: &str = "audit_export_interval_hours";
const AUDIT_EXPORT_LAST_AT_KEY: &str = "audit_export_last_at";
const AUDIT_EXPORT_LAST_SUCCESS_KEY: &str = "audit_export_last_success_at";
const AUDIT_EXPORT_LAST_ERROR_KEY: &str = "audit_export_last_error";
const AUDIT_MAINTENANCE_INTERVAL_SECS: u64 = 15 * 60;

/// A retention window is either "keep forever" (0) or a bounded number of
/// days. The upper bound keeps a malformed setting from looking like an
/// accidental request to erase everything.
fn valid_audit_retention_days(days: u32) -> bool {
    days == 0 || (1..=3650).contains(&days)
}

/// Read the persisted policy. Missing, malformed, or out-of-range values mean
/// "keep forever" — the safe default for an append-only audit trail.
async fn configured_audit_retention(pool: &sqlx::SqlitePool) -> Option<u32> {
    let raw = ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_RETENTION_KEY)
        .await
        .ok()
        .flatten()?;
    let days = raw.trim().parse::<u32>().ok()?;
    valid_audit_retention_days(days).then_some(days)
}

/// Run one retention pass. Returns `None` when the policy is disabled or
/// unreadable, and the deleted count otherwise. Errors are logged, not
/// propagated: a background cleanup must not take the app down.
async fn run_audit_retention(pool: &sqlx::SqlitePool) -> Option<u64> {
    let days = configured_audit_retention(pool).await?;
    if days == 0 {
        return None;
    }
    match ravenbot_governance::AuditLogger::new(pool.clone())
        .prune(days)
        .await
    {
        Ok(deleted) => Some(deleted),
        Err(error) => {
            tracing::warn!(error = %error, "Automatic audit retention failed");
            None
        }
    }
}

fn valid_audit_export_interval(hours: u32) -> bool {
    hours == 0 || (1..=168).contains(&hours)
}

fn audit_export_due(
    interval_hours: u32,
    last_at: Option<&str>,
    now: chrono::DateTime<chrono::Utc>,
) -> bool {
    if interval_hours == 0 {
        return false;
    }
    let Some(last_at) = last_at else {
        return true;
    };
    let Ok(last_at) = chrono::DateTime::parse_from_rfc3339(last_at) else {
        return true;
    };
    now.signed_duration_since(last_at.with_timezone(&chrono::Utc))
        .num_seconds()
        >= i64::from(interval_hours) * 3600
}

fn audit_export_directory(raw: &str) -> Result<std::path::PathBuf, String> {
    let raw = raw.trim();
    if raw.is_empty() {
        return Err("Choose a folder for scheduled audit exports.".to_string());
    }
    if raw.len() > 4096 {
        return Err("The audit export folder path is too long.".to_string());
    }
    let path = std::path::PathBuf::from(raw);
    if !path.is_absolute() {
        return Err("Choose an absolute audit export folder.".to_string());
    }
    if !path.is_dir() {
        return Err("The audit export folder does not exist.".to_string());
    }
    let path = path
        .canonicalize()
        .map_err(|error| format!("Could not resolve the audit export folder: {error}"))?;
    let probe = path.join(format!(".ravenbot-export-test-{}", Uuid::new_v4()));
    std::fs::write(&probe, b"probe")
        .map_err(|error| format!("The audit export folder is not writable: {error}"))?;
    let _ = std::fs::remove_file(&probe);
    Ok(path)
}

fn scheduled_audit_export_path(directory: &std::path::Path) -> std::path::PathBuf {
    let stamp = chrono::Utc::now().format("%Y%m%dT%H%M%SZ");
    let mut path = directory.join(format!("ravenbot-audit-{stamp}.json"));
    if path.exists() {
        for index in 1..1000 {
            path = directory.join(format!("ravenbot-audit-{stamp}-{index}.json"));
            if !path.exists() {
                return path;
            }
        }
        path = directory.join(format!("ravenbot-audit-{stamp}-{}.json", Uuid::new_v4()));
    }
    path
}

fn clip_audit_export_error(error: &str) -> String {
    error.chars().take(500).collect()
}

async fn record_audit_export_attempt(pool: &sqlx::SqlitePool, error: Option<&str>) {
    let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, false);
    let _ =
        ravenbot_db::queries::AppSettingsQueries::set(pool, AUDIT_EXPORT_LAST_AT_KEY, &now).await;
    let _ = ravenbot_db::queries::AppSettingsQueries::set(
        pool,
        AUDIT_EXPORT_LAST_ERROR_KEY,
        error
            .map(clip_audit_export_error)
            .unwrap_or_default()
            .as_str(),
    )
    .await;
}

#[derive(Debug, Clone, serde::Serialize)]
struct ScheduledAuditExport {
    path: String,
    count: u64,
    bytes: usize,
    sha256: String,
    public_key: String,
}

/// Write a signed full audit export if the configured interval has elapsed.
/// The last-attempt timestamp is recorded even on failure so a broken folder
/// is retried on the normal cadence, not once every maintenance tick.
async fn run_audit_export_if_due(
    pool: &sqlx::SqlitePool,
) -> Option<Result<ScheduledAuditExport, String>> {
    let interval_hours =
        ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_INTERVAL_KEY)
            .await
            .ok()
            .flatten()
            .and_then(|value| value.trim().parse::<u32>().ok())
            .filter(|hours| valid_audit_export_interval(*hours))
            .unwrap_or(0);
    if interval_hours == 0 {
        return None;
    }
    let directory = ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_DIR_KEY)
        .await
        .ok()
        .flatten()
        .unwrap_or_default();
    let last_at = ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_LAST_AT_KEY)
        .await
        .ok()
        .flatten();
    if !audit_export_due(interval_hours, last_at.as_deref(), chrono::Utc::now()) {
        return None;
    }

    let directory = match audit_export_directory(&directory) {
        Ok(directory) => directory,
        Err(error) => {
            record_audit_export_attempt(pool, Some(&error)).await;
            return Some(Err(error));
        }
    };
    let path = scheduled_audit_export_path(&directory);
    // The first scheduled backup is a full snapshot. Later backups are
    // incremental from the last successful attempt, which keeps files bounded
    // and avoids a 50k-entry cap deadlock while retention is paused on failure.
    let last_success =
        ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_LAST_SUCCESS_KEY)
            .await
            .ok()
            .flatten()
            .filter(|value| !value.trim().is_empty());
    let export = match build_audit_export(
        pool,
        ravenbot_governance::AuditExportFilters {
            since: last_success,
            ..Default::default()
        },
    )
    .await
    {
        Ok(export) => export,
        Err(error) => {
            record_audit_export_attempt(pool, Some(&error)).await;
            return Some(Err(error));
        }
    };
    if let Err(error) = write_audit_export(&path, export.json.as_bytes()) {
        record_audit_export_attempt(pool, Some(&error)).await;
        return Some(Err(error));
    }
    record_audit_export_attempt(pool, None).await;
    let _ = ravenbot_db::queries::AppSettingsQueries::set(
        pool,
        AUDIT_EXPORT_LAST_SUCCESS_KEY,
        &chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, false),
    )
    .await;
    Some(Ok(ScheduledAuditExport {
        path: path.to_string_lossy().to_string(),
        count: export.count,
        bytes: export.bytes,
        sha256: export.sha256,
        public_key: export.public_key,
    }))
}

async fn audit_export_schedule_json(pool: &sqlx::SqlitePool) -> Result<serde_json::Value, String> {
    let directory = ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_DIR_KEY)
        .await
        .map_err(|error| error.to_string())?
        .filter(|value| !value.trim().is_empty());
    let interval_hours =
        ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_INTERVAL_KEY)
            .await
            .map_err(|error| error.to_string())?
            .and_then(|value| value.trim().parse::<u32>().ok())
            .filter(|hours| valid_audit_export_interval(*hours))
            .unwrap_or(0);
    let last_at = ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_LAST_AT_KEY)
        .await
        .map_err(|error| error.to_string())?;
    let last_error =
        ravenbot_db::queries::AppSettingsQueries::get(pool, AUDIT_EXPORT_LAST_ERROR_KEY)
            .await
            .map_err(|error| error.to_string())?
            .filter(|value| !value.trim().is_empty());
    Ok(serde_json::json!({
        "directory": directory,
        "interval_hours": interval_hours,
        "last_at": last_at,
        "last_error": last_error,
    }))
}

#[tauri::command]
async fn get_audit_export_schedule(
    state: State<'_, AppState>,
) -> Result<serde_json::Value, String> {
    audit_export_schedule_json(state.db.pool()).await
}

#[tauri::command]
async fn set_audit_export_schedule(
    state: State<'_, AppState>,
    directory: Option<String>,
    interval_hours: u32,
) -> Result<serde_json::Value, String> {
    if !valid_audit_export_interval(interval_hours) {
        return Err("Scheduled exports must be off or between 1 and 168 hours.".to_string());
    }
    let directory = match directory
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(raw) => Some(audit_export_directory(raw)?.to_string_lossy().to_string()),
        None if interval_hours > 0 => {
            return Err("Choose a folder for scheduled audit exports.".to_string())
        }
        None => None,
    };
    ravenbot_db::queries::AppSettingsQueries::set(
        state.db.pool(),
        AUDIT_EXPORT_INTERVAL_KEY,
        &interval_hours.to_string(),
    )
    .await
    .map_err(|error| error.to_string())?;
    ravenbot_db::queries::AppSettingsQueries::set(
        state.db.pool(),
        AUDIT_EXPORT_DIR_KEY,
        directory.as_deref().unwrap_or(""),
    )
    .await
    .map_err(|error| error.to_string())?;

    let exported = if interval_hours > 0 {
        run_audit_export_if_due(state.db.pool()).await
    } else {
        None
    };
    if let Some(Err(error)) = &exported {
        return Err(error.clone());
    }
    let mut schedule = audit_export_schedule_json(state.db.pool()).await?;
    schedule["exported"] = match exported {
        Some(Ok(export)) => serde_json::to_value(export).map_err(|error| error.to_string())?,
        _ => serde_json::Value::Null,
    };
    Ok(schedule)
}

#[tauri::command]
async fn get_audit_retention(state: State<'_, AppState>) -> Result<u32, String> {
    Ok(configured_audit_retention(state.db.pool())
        .await
        .unwrap_or(0))
}

/// Save the automatic-retention policy and prune immediately.
///
/// The UI warns that saving a finite window is destructive. Doing the first
/// pass here means the user sees the effect (and the deleted count) instead of
/// waiting up to six hours for the background loop.
#[tauri::command]
async fn set_audit_retention(
    state: State<'_, AppState>,
    days: u32,
) -> Result<serde_json::Value, String> {
    if !valid_audit_retention_days(days) {
        return Err("Audit retention must be 0 (forever) or between 1 and 3650 days.".to_string());
    }
    ravenbot_db::queries::AppSettingsQueries::set(
        state.db.pool(),
        AUDIT_RETENTION_KEY,
        &days.to_string(),
    )
    .await
    .map_err(|error| error.to_string())?;
    let deleted = if days > 0 {
        state.runtime.audit_logger().prune(days).await?
    } else {
        0
    };
    Ok(serde_json::json!({ "days": days, "deleted": deleted }))
}

/// Shape the run list, including whether the thread has a tool trace worth
/// learning from. Split from the command so the SQL is exercised by a test.
async fn list_runs_view(pool: &sqlx::SqlitePool, limit: i64) -> Result<serde_json::Value, String> {
    let rows: Vec<(
        String,
        String,
        String,
        String,
        i64,
        f64,
        String,
        String,
        Option<String>,
        Option<String>,
        Option<String>,
        Option<String>,
        i64,
    )> = sqlx::query_as(
        "SELECT r.id, r.bot_id, r.thread_id, r.state, r.tokens_consumed, r.cost_estimate,
                r.created_at, r.updated_at, r.completed_at, r.outcome,
                ra.actor_name, ra.role,
                EXISTS(
                    SELECT 1 FROM messages m
                    WHERE m.thread_id = r.thread_id
                      AND m.role = 'assistant'
                      AND json_valid(m.content) = 1
                      AND json_array_length(json_extract(m.content, '$.tools')) > 0
                ) AS has_trace
         FROM runs r
         LEFT JOIN run_actors ra ON ra.run_id = r.id
         ORDER BY r.created_at DESC LIMIT ?",
    )
    .bind(limit)
    .fetch_all(pool)
    .await
    .map_err(|e| e.to_string())?;

    let mut out = Vec::with_capacity(rows.len());
    for (
        id,
        bot_id,
        thread_id,
        state,
        tokens,
        cost,
        created,
        updated,
        completed,
        outcome,
        actor_name,
        actor_role,
        has_trace,
    ) in rows
    {
        out.push(serde_json::json!({
            "id": id,
            "bot_id": bot_id,
            "thread_id": thread_id,
            "state": state,
            "tokens_consumed": tokens,
            "cost_estimate": cost,
            "created_at": created,
            "updated_at": updated,
            "completed_at": completed,
            "outcome": outcome,
            "actor_name": actor_name,
            "actor_role": actor_role,
            "has_trace": has_trace != 0,
        }));
    }
    Ok(serde_json::Value::Array(out))
}

/// List recent runs for diagnostics, newest first.
