// ——— Budgets — real enforcement + tracking ———

#[tauri::command]
async fn get_bot_budget(
    state: State<'_, AppState>,
    bot_id: Uuid,
) -> Result<serde_json::Value, String> {
    let budgets = ravenbot_governance::BudgetManager::new(state.db.pool().clone());
    let budget = budgets
        .get_budget(bot_id)
        .await
        .map_err(|e| e.to_string())?;
    let (tokens_used, cost_used) = budgets.get_usage(bot_id).await.map_err(|e| e.to_string())?;
    let check = budgets
        .check_budget(bot_id)
        .await
        .map_err(|e| e.to_string())?;

    Ok(serde_json::json!({
        "budget": budget.map(|b| serde_json::json!({
            "limit": match &b.limit {
                ravenbot_core::BudgetLimit::Unlimited => serde_json::json!({"kind": "unlimited"}),
                ravenbot_core::BudgetLimit::Tokens { max } => serde_json::json!({"kind": "tokens", "max": max}),
                ravenbot_core::BudgetLimit::Cost { max } => serde_json::json!({"kind": "cost", "max": max}),
            },
            "period": match b.period {
                ravenbot_core::BudgetPeriod::Hourly => "hourly",
                ravenbot_core::BudgetPeriod::Daily => "daily",
                ravenbot_core::BudgetPeriod::Weekly => "weekly",
                ravenbot_core::BudgetPeriod::Monthly => "monthly",
                ravenbot_core::BudgetPeriod::Total => "total",
            },
            "behavior": match b.behavior {
                ravenbot_core::BudgetBehavior::HardStop => "hard_stop",
                ravenbot_core::BudgetBehavior::Warn => "warn",
                ravenbot_core::BudgetBehavior::AskUser => "ask_user",
            },
        })),
        "tokens_used": tokens_used,
        "cost_used": cost_used,
        "percentage_used": check.percentage_used,
        "allowed": check.allowed,
        "should_warn": check.should_warn,
    }))
}

#[tauri::command]
async fn set_bot_budget(
    state: State<'_, AppState>,
    bot_id: Uuid,
    kind: String,
    max: f64,
    period: String,
    behavior: Option<String>,
) -> Result<(), String> {
    let limit = match kind.as_str() {
        "tokens" => ravenbot_core::BudgetLimit::Tokens { max: max as u64 },
        "cost" => ravenbot_core::BudgetLimit::Cost { max },
        _ => ravenbot_core::BudgetLimit::Unlimited,
    };
    let budget_period = match period.as_str() {
        "hourly" => ravenbot_core::BudgetPeriod::Hourly,
        "daily" => ravenbot_core::BudgetPeriod::Daily,
        "weekly" => ravenbot_core::BudgetPeriod::Weekly,
        "monthly" => ravenbot_core::BudgetPeriod::Monthly,
        _ => ravenbot_core::BudgetPeriod::Total,
    };
    let behavior = match behavior
        .as_deref()
        .map(str::trim)
        .unwrap_or("hard_stop")
        .to_ascii_lowercase()
        .as_str()
    {
        "warn" => ravenbot_core::BudgetBehavior::Warn,
        "ask_user" => ravenbot_core::BudgetBehavior::AskUser,
        _ => ravenbot_core::BudgetBehavior::HardStop,
    };
    let mut budget = ravenbot_core::Budget::new(bot_id, limit, budget_period);
    budget.behavior = behavior;
    let budgets = ravenbot_governance::BudgetManager::new(state.db.pool().clone());
    budgets.set_budget(&budget).await
}

#[tauri::command]
async fn get_tool_prices(
    state: State<'_, AppState>,
) -> Result<std::collections::HashMap<String, f64>, String> {
    let raw = ravenbot_db::queries::AppSettingsQueries::get(state.db.pool(), "tool_prices")
        .await
        .map_err(|error| error.to_string())?;
    Ok(raw
        .as_deref()
        .and_then(|value| serde_json::from_str(value).ok())
        .unwrap_or_default())
}

#[tauri::command]
async fn set_tool_prices(
    state: State<'_, AppState>,
    prices: std::collections::HashMap<String, f64>,
) -> Result<(), String> {
    if prices.len() > 100 {
        return Err("At most 100 tool prices can be configured.".to_string());
    }
    let mut clean = std::collections::HashMap::new();
    for (tool, price) in prices {
        let tool = tool.trim().to_string();
        if tool.is_empty()
            || tool.chars().count() > 64
            || !tool
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.'))
        {
            return Err(format!("Invalid tool id: {tool}"));
        }
        if !price.is_finite() || !(0.0..=1000.0).contains(&price) {
            return Err(format!("Price for {tool} must be between 0 and 1000."));
        }
        if price > 0.0 {
            clean.insert(tool, price);
        }
    }
    let encoded = serde_json::to_string(&clean).map_err(|error| error.to_string())?;
    ravenbot_db::queries::AppSettingsQueries::set(state.db.pool(), "tool_prices", &encoded)
        .await
        .map_err(|error| error.to_string())
}

